import React, { FC, HTMLAttributes, ReactNode } from 'react'
import cx from 'classnames'

export type GridProps = HTMLAttributes<HTMLDivElement> & {
  className?: string | object
  children?: ReactNode
}

export const Grid: FC<GridProps> = ({ className, children, ...props }: GridProps): JSX.Element => {
  return (
    <div {...props} className={cx('ui-grid', className)}>
      {children}
    </div>
  )
}
