import { styled } from '@linaria/react'
import React, { FC } from 'react'
import { useTheme } from '@utils/hooks'
import { ThemeMode, ThemeProp } from '@utils/constants'

export const ThemeSwitcher: FC = (): JSX.Element => {
  const { theme, setMode } = useTheme()

  return (
    <Wrapper theme={theme}>
      <Button onClick={() => setMode(ThemeMode.Light)}>L</Button>
      <Splitter>|</Splitter>
      <Button onClick={() => setMode(ThemeMode.Dark)}>D</Button>
    </Wrapper>
  )
}

const Wrapper = styled.div<ThemeProp>`
  display: flex;
  align-items: center;
  position: fixed;
  right: 10px;
  top: 10px;
  font-size: 12px;
  z-index: 1;
  color: ${(props) => props.theme.colors.accent};
`

const Splitter = styled.span`
  margin: 0 5px;
  padding: 7px 0;
`

const Button = styled.button`
  cursor: pointer;
  color: inherit;
  padding: 7px;
  border: none;
  background: transparent;
  font-size: 13px;
`
